<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$supplier=(int)$_POST['supplier_id'];$mid=(int)$_POST['medicine_id'];$boxes=max(0,(int)$_POST['boxes']);$strips=max(0,(int)$_POST['strips']);$tabs=max(0,(int)$_POST['tablets']);$m=$db->prepare('SELECT * FROM medicines WHERE id=? AND active=1');$m->execute([$mid]);$med=$m->fetch();if(!$med)throw new RuntimeException('Medicine not found.');$qty=$boxes*(int)$med['strips_per_box']*(int)$med['units_per_strip']+$strips*(int)$med['units_per_strip']+$tabs;if($qty<1)throw new RuntimeException('Enter at least one box, strip, or tablet.');$cost=max(0,(float)$_POST['unit_cost']);$total=$qty*$cost;$paid=min($total,max(0,(float)$_POST['paid']));$db->beginTransaction();$invoice='PUR-'.date('YmdHis').'-'.random_int(10,99);$db->prepare('INSERT INTO purchases(invoice_no,supplier_id,subtotal,paid) VALUES(?,?,?,?)')->execute([$invoice,$supplier,$total,$paid]);$pid=(int)$db->lastInsertId();$db->prepare('INSERT INTO batches(medicine_id,batch_no,expiry_date,units_received,units_remaining,purchase_unit_cost) VALUES(?,?,?,?,?,?)')->execute([$mid,trim($_POST['batch_no'])?:null,$_POST['expiry_date']?:null,$qty,$qty,$cost]);$bid=(int)$db->lastInsertId();$db->prepare('INSERT INTO purchase_items(purchase_id,medicine_id,batch_id,quantity_units,unit_cost,line_total) VALUES(?,?,?,?,?,?)')->execute([$pid,$mid,$bid,$qty,$cost,$total]);$db->prepare("INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,reference_id,note) VALUES(?,?, 'purchase',?,?,?)")->execute([$mid,$bid,$qty,$pid,'Purchase '.$invoice]);$db->prepare('UPDATE suppliers SET balance=balance+? WHERE id=?')->execute([$total-$paid,$supplier]);$db->commit();header('Location: purchases.php?saved=1');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$suppliers=$db->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();$meds=$db->query('SELECT * FROM medicines WHERE active=1 ORDER BY name')->fetchAll();$purchases=$db->query('SELECT p.*,s.name supplier FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.id DESC LIMIT 100')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Purchases</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">PURCHASING</div><h1>Purchases</h1><p>Receive supplier purchases directly into batch stock.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Purchase saved and stock added.</div><?php endif;?><section class="panel"><h2>New Purchase</h2><form method="post" class="grid"><label>Supplier<select name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Medicine<select name="medicine_id" required><option value="">Select medicine</option><?php foreach($meds as $m):?><option value="<?=$m['id']?>"><?=e($m['name'])?></option><?php endforeach;?></select></label><label>Batch <span class="optional">(optional)</span><input name="batch_no"></label><label>Expiry <span class="optional">(optional)</span><input type="date" name="expiry_date"></label><label>Boxes<input type="number" name="boxes" min="0" value="0"></label><label>Strips<input type="number" name="strips" min="0" value="0"></label><label>Loose tablets<input type="number" name="tablets" min="0" value="0"></label><label>Cost / tablet<input type="number" name="unit_cost" step="0.0001" min="0" value="0"></label><label>Paid now<input type="number" name="paid" step="0.01" min="0" value="0"></label><button class="btn">Save Purchase & Add Stock</button></form></section><section class="panel"><h2>Purchase History</h2><table><tr><th>Invoice</th><th>Supplier</th><th>Subtotal</th><th>Paid</th><th>Due</th><th>Date</th></tr><?php foreach($purchases as $p):?><tr><td><?=e($p['invoice_no'])?></td><td><?=e($p['supplier']??'—')?></td><td>Rs. <?=money($p['subtotal'])?></td><td>Rs. <?=money($p['paid'])?></td><td>Rs. <?=money(max(0,(float)$p['subtotal']-(float)$p['paid']))?></td><td><?=e($p['created_at'])?></td></tr><?php endforeach;?></table></section></main></body></html>